import{_ as t,c as s,o as i,j as e,a as r}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"卷三·15","description":"易小帖 - 卷三·15","frontmatter":{"title":"卷三·15","description":"易小帖 - 卷三·15"},"headers":[],"relativePath":"zh/classics/yixiaotie/083.md","filePath":"zh/classics/yixiaotie/083.md"}'),o={name:"zh/classics/yixiaotie/083.md"};function c(n,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"卷三·15",tabindex:"-1"},[r("卷三·15 "),e("a",{class:"header-anchor",href:"#卷三·15","aria-label":"Permalink to “卷三·15”"},"​")],-1),e("p",null,"乾坤二策，其數正合三百六十，以乾二百一十六，坤一百四十四，合之剛三百六十也。其他屯蒙需訟四卦，則屯蒙二陽，需訟四陽，合得六陽，屯蒙四陰，需訟二陰，亦合得六陰，正與乾坤二卦六陽六陰相合，則其數亦自應三百六十，此不須計也。又推之師比小畜履四卦，師比一陽五陰，小畜履一陰五陽，又適與乾坤六陽六陰合，亦適得三百六十之數。遂妄起推測，以為上下經序卦之例，皆以三百六十數為度。自邵氏闡先天圖後，凡南宋言易者，爭相趨附，乃作上下序卦例圖，於以合於《皇極經世》運會之數，及推之泰否同人大有四卦，則泰否三陽三陰，同人大有五陽一陰，合之得八陽四陰，共四百一十四策，是必退其贏以合之三百六十。謙豫隨蠱四卦，則謙豫一陽五陰，隨蠱三陽三陰，合之得四陽八陰，又必增其缺以合之三百六十，則全易萬有一千五百二十之策，原合上下經六十四卦三百八十四爻之數，而統成之，既可那移，則雖乾坤倒排，六子混列，彼此那移，何嘗不合，而以之定序卦數例，此欲效狙公狡儈作暮四朝三之術，而又不能矣。宋人竊前儒一說，遂矜為獨得，即以此反訾前儒，及其既而浸淫無忌，竟纂易聖言，而不之過。然倒底紕漏，向使京焦施孟之徒，有一於此，則華山授受，何處駐足。況邵蔡後人之璅璅者與。",-1)])])}const h=t(o,[["render",c]]);export{f as __pageData,h as default};
